import sys

def solve():
    input_data = sys.stdin.read().split()
    idx = 0

    t = int(input_data[idx])
    idx += 1

    results = []

    for _ in range(t):
        n = int(input_data[idx])
        m = int(input_data[idx+1])
        idx += 2

        grid = []
        for r in range(n):
            row = []
            for c in range(m):
                row.append(int(input_data[idx]))
                idx += 1
            grid.append(row)

        bad_cols = []
        for r in range(n):
            for c in range(1, m):
                if grid[r][c] < grid[r][c-1]:
                    bad_cols.append((r, c-1, c))

        if not bad_cols:
            results.append("1 1")
            continue

        if len(bad_cols) > 2 * m:
            results.append("-1")
            continue

        candidates = set()
        for r, c1, c2 in bad_cols:
            candidates.add(c1)
            candidates.add(c2)

        if len(candidates) > 2:
            results.append("-1")
            continue

        cand_list = sorted(list(candidates))
        found = False
        ans_pair = None

        for i in range(len(cand_list)):
            for j in range(i, len(cand_list)):
                c1, c2 = cand_list[i], cand_list[j]

                temp_grid = [row[:] for row in grid]
                for r in range(n):
                    temp_grid[r][c1], temp_grid[r][c2] = temp_grid[r][c2], temp_grid[r][c1]

                ok = True
                for r in range(n):
                    for c in range(1, m):
                        if temp_grid[r][c] < temp_grid[r][c-1]:
                            ok = False
                            break
                    if not ok:
                        break

                if ok:
                    ans_pair = (c1 + 1, c2 + 1)
                    found = True
                    break
            if found:
                break

        if found:
            results.append(f"{ans_pair[0]} {ans_pair[1]}")
        else:
            results.append("-1")

    print("\n".join(results))

if __name__ == "__main__":
    solve()
